package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.cfg.ConfigOverride;
import com.fasterxml.jackson.databind.cfg.DeserializationConfig;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.deser.BeanDeserializerModifier;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.std.ThrowableDeserializer;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.ser.BeanDescription;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.SimpleBeanPropertyDefinition;
import com.fasterxml.jackson.databind.util.StdDeserializer;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for BeanDeserializerFactory#findStdDeserializer.
 * Since the method is protected, we use a subclass to expose it for testing.
 */
public class BeanDeserializerFactory_findStdDeserializer_TriageGen1Test {

    @Mock
    private DeserializationContext ctxt;
    @Mock
    private JavaType type;
    @Mock
    private BeanDescription beanDesc;
    @Mock
    private DeserializationConfig config;
    @Mock
    private BeanDeserializerModifier modifier;

    private TestableBeanDeserializerFactory factory;

    // A subclass to expose the protected method
    private static class TestableBeanDeserializerFactory extends BeanDeserializerFactory {
        private final DeserializerFactoryConfig mockConfig;

        public TestableBeanDeserializerFactory(DeserializerFactoryConfig config) {
            super(config);
            this.mockConfig = config;
        }

        @Override
        public JsonDeserializer<?> findStdDeserializer(DeserializationContext ctxt, JavaType type, BeanDescription beanDesc)
                throws JsonMappingException {
            return super.findStdDeserializer(ctxt, type, beanDesc);
        }

        // Overriding to control the behavior of findDefaultDeserializer which is called by findStdDeserializer
        // In a real Jackson environment, findDefaultDeserializer is part of the internal logic.
        // Here we mock the factory logic via spies or controlled config.
    }

    // Mock implementation of DeserializerFactoryConfig to control modifiers
    private static class MockDeserializerFactoryConfig implements DeserializerFactoryConfig {
        private final List<BeanDeserializerModifier> modifiers;

        public MockDeserializerFactoryConfig(List<BeanDeserializerModifier> modifiers) {
            this.modifiers = modifiers;
        }

        @Override
        public boolean hasDeserializerModifiers() {
            return !modifiers.isEmpty();
        }

        @Override
        public List<BeanDeserializerModifier> deserializerModifiers() {
            return modifiers;
        }
    }

    // We need to spy on the factory to mock findDefaultDeserializer because it's an internal call
    private TestableBeanDeserializerFactory spyFactory;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        when(ctxt.getConfig()).thenReturn(config);
    }

    @Test
    public void testFindStdDeserializer_ReturnsNullWhenDefaultIsNull() throws JsonMappingException {
        DeserializerFactoryConfig configObj = mock(DeserializerFactoryConfig.class);
        when(configObj.hasDeserializerModifiers()).thenReturn(true);
        when(configObj.deserializerModifiers()).thenReturn(Collections.emptyList());

        spyFactory = spy(new TestableBeanDeserializerFactory(configObj));

        // Mock findDefaultDeserializer to return null
        doReturn(null).when(spyFactory).findDefaultDeserializer(ctxt, type, beanDesc);

        JsonDeserializer<?> result = spyFactory.findStdDeserializer(ctxt, type, beanDesc);

        assertNull(result);
        verify(spyFactory).findDefaultDeserializer(ctxt, type, beanDesc);
    }

    @Test
    public void testFindStdDeserializer_NoModifiers() throws JsonMappingException {
        DeserializerFactoryConfig configObj = mock(DeserializerFactoryConfig.class);
        when(configObj.hasDeserializerModifiers()).thenReturn(false);

        spyFactory = spy(new TestableBeanDeserializerFactory(configObj));
        JsonDeserializer<?> originalDeser = new StdDeserializer<Object>(Object.class) {};

        doReturn(originalDeser).when(spyFactory).findDefaultDeserializer(ctxt, type, beanDesc);

        JsonDeserializer<?> result = spyFactory.findStdDeserializer(ctxt, type, beanDesc);

        assertEquals(originalDeser, result);
    }

    @Test
    public void testFindStdDeserializer_WithModifiers() throws JsonMappingException {
        JsonDeserializer<?> originalDeser = new StdDeserializer<Object>(Object.class) {};
        JsonDeserializer<?> modifiedDeser = new StdDeserializer<Object>(Object.class) {};

        // Setup modifiers
        DeserializerFactoryConfig configObj = mock(DeserializerFactoryConfig.class);
        when(configObj.hasDeserializerModifiers()).thenReturn(true);
        when(configObj.deserializerModifiers()).thenReturn(Collections.singletonList(modifier));

        spyFactory = spy(new TestableBeanDeserializerFactory(configObj));
        doReturn(originalDeser).when(spyFactory).findDefaultDeserializer(ctxt, type, beanDesc);

        // Mock modifier behavior
        when(modifier.modifyDeserializer(config, beanDesc, originalDeser)).thenReturn(modifiedDeser);

        JsonDeserializer<?> result = spyFactory.findStdDeserializer(ctxt, type, beanDesc);

        assertEquals(modifiedDeser, result);
        verify(modifier).modifyDeserializer(config, beanDesc, originalDeser);
    }

    @Test
    public void testFindStdDeserializer_MultipleModifiers() throws JsonMappingException {
        JsonDeserializer<?> deser0 = new StdDeserializer<Object>(Object.class) {};
        JsonDeserializer<?> deser1 = new StdDeserializer<Object>(Object.class) {};
        JsonDeserializer<?> deser2 = new StdDeserializer<Object>(Object.class) {};

        BeanDeserializerModifier mod1 = mock(BeanDeserializerModifier.class);
        BeanDeserializerModifier mod2 = mock(BeanDeserializerModifier.class);

        DeserializerFactoryConfig configObj = mock(DeserializerFactoryConfig.class);
        when(configObj.hasDeserializerModifiers()).thenReturn(true);
        when(configObj.deserializerModifiers()).thenReturn(List.of(mod1, mod2));

        spyFactory = spy(new TestableBeanDeserializerFactory(configObj));
        doReturn(deser0).when(spyFactory).findDefaultDeserializer(ctxt, type, beanDesc);

        // Mod1 changes deser0 to deser1
        when(mod1.modifyDeserializer(config, beanDesc, deser0)).thenReturn(deser1);
        // Mod2 changes deser1 to deser2
        when(mod2.modifyDeserializer(config, beanDesc, deser1)).thenReturn(deser2);

        JsonDeserializer<?> result = spyFactory.findStdDeserializer(ctxt, type, beanDesc);

        assertEquals(deser2, result);
        verify(mod1).modifyDeserializer(config, beanDesc, deser0);
        verify(mod2).modifyDeserializer(config, beanDesc, deser1);
    }
}
